/// <summary>
/// The <c>AVASysCorpNetActivePrintersDbt_Extension</c> represents a extension of SysCorpNetActivePrinter.
/// </summary>
[
    ExtensionOf(viewstr(SysCorpNetActivePrinters))
]
final class AVASysCorpNetActivePrintersDbt_Extension
{
}

Method.Source:
/// <summary>
/// Methode to find printer by name
/// </summary>
/// <param name = "_printerCode">
/// Printer code to find a not on prem printer
/// </param>
/// <returns>
/// the found instance of SysCorpNetActivePrinters
/// </returns>
/// <remarks>
/// AVA_007831_MDEChangePrinter
/// </remarks>
public static SysCorpNetActivePrinters avaFindByPrinterName(AVAPrinterCode _printerCode)
{
    SysCorpNetActivePrinters    sysCorpNetActivePrinters;

    select firstonly sysCorpNetActivePrinters
        where sysCorpNetActivePrinters.PrinterName == _printerCode;

    return sysCorpNetActivePrinters;
}
